// =========================================================================
// JIRACHI NGÔI SAO BAN ĐIỀU ƯỚC THIÊN HÀ (MYTHIC JIRACHI WISH MAKER)
// Modern HTML5 Canvas 2D Implementation - 60 FPS Fluid Physics
// Pop Mart / Vinyl High-End 3D Sculpting & Micro-Physics Engine
// =========================================================================
function drawJirachiWishMaker(ctx, cx, cy, scale, t) {
  ctx.save();

  // -----------------------------------------------------------------------
  // 1. CHUYỂN ĐỘNG VI VẬT LÝ HỮU CƠ (ORGANIC MICRO-PHYSICS)
  // -----------------------------------------------------------------------
  const breathFreq = 1.8;
  const breathPhase = t * breathFreq;
  const hoverOffsetY = Math.sin(breathPhase) * 4.0;
  const by = cy + hoverOffsetY;

  // Squash & Stretch đàn hồi 5% (Area preservation)
  const sY = 1.0 + 0.05 * Math.sin(breathPhase);
  const sX = 1.0 - 0.03 * Math.sin(breathPhase);

  // Trễ pha động học 3 dải bùa (Delta Phi = 0.45 rad)
  const lagTagTop   = breathPhase - 0.45;
  const lagTagLeft  = breathPhase - 0.45 - 0.15;
  const lagTagRight = breathPhase - 0.45 + 0.15;

  // Trễ pha tà áo lụa phía sau lưng (Delta Phi = 0.60 rad)
  const lagSashL = breathPhase - 0.60;
  const lagSashR = breathPhase - 0.55;

  // Trễ pha tai mũ rủ hai bên má (Delta Phi = 0.20 rad)
  const lagLappet = breathPhase - 0.20;
  const lappetSway = Math.sin(lagLappet) * 2.0;

  // Chu kỳ chớp mắt tự nhiên 3.5s
  const blinkCycle = (t * 1000) % 3500;
  const blink = (blinkCycle < 140);

  ctx.translate(cx, by);
  ctx.scale(scale, scale);

  // -----------------------------------------------------------------------
  // 2. LỚP 1: BÓNG TIẾP XÚC MẶT SÀN (FLOOR CONTACT SHADOW)
  // -----------------------------------------------------------------------
  ctx.save();
  const floorRelY = (cy + 44) - by;
  const shRadiusX = (28.0 - hoverOffsetY * 1.5) * sX;
  const shRadiusY = (7.0 - hoverOffsetY * 0.4);
  const shadowAlpha = 0.35 + (hoverOffsetY / 4.0) * 0.15;

  const shadowGrad = ctx.createRadialGradient(0, floorRelY, 2, 0, floorRelY, Math.max(8, shRadiusX));
  shadowGrad.addColorStop(0, `rgba(15, 23, 42, ${shadowAlpha})`);
  shadowGrad.addColorStop(0.5, `rgba(148, 163, 184, ${shadowAlpha * 0.6})`);
  shadowGrad.addColorStop(1, "rgba(148, 163, 184, 0)");
  ctx.fillStyle = shadowGrad;
  ctx.beginPath();
  ctx.ellipse(0, floorRelY, Math.max(8, shRadiusX), Math.max(3, shRadiusY), 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // -----------------------------------------------------------------------
  // 3. LỚP 2: TÀ ÁO LỤA THIÊN HÀ BAY BỔNG SAU LƯNG (FLOWING SILK SASHES)
  // -----------------------------------------------------------------------
  ctx.save();
  const sashWaveL = Math.sin(lagSashL) * 5.0;
  const sashWaveR = Math.sin(lagSashR) * 5.0;

  // Tà áo lụa trái
  const sashLGrad = ctx.createLinearGradient(-8, 12, -52, 24 + sashWaveL);
  sashLGrad.addColorStop(0, "rgba(253, 224, 71, 0.95)");
  sashLGrad.addColorStop(0.6, "rgba(254, 240, 138, 0.85)");
  sashLGrad.addColorStop(1, "rgba(254, 249, 195, 0.6)");
  ctx.fillStyle = sashLGrad;
  ctx.beginPath();
  ctx.moveTo(-8, 11);
  ctx.bezierCurveTo(-22, 14 + sashWaveL * 0.5, -38, 16 + sashWaveL, -52, 23 + sashWaveL);
  ctx.bezierCurveTo(-46, 30 + sashWaveL, -28, 25 + sashWaveL * 0.5, -8, 18);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = "rgba(255, 247, 160, 0.8)";
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // Tà áo lụa phải
  const sashRGrad = ctx.createLinearGradient(8, 12, 52, 24 + sashWaveR);
  sashRGrad.addColorStop(0, "rgba(253, 224, 71, 0.95)");
  sashRGrad.addColorStop(0.6, "rgba(254, 240, 138, 0.85)");
  sashRGrad.addColorStop(1, "rgba(254, 249, 195, 0.6)");
  ctx.fillStyle = sashRGrad;
  ctx.beginPath();
  ctx.moveTo(8, 11);
  ctx.bezierCurveTo(22, 14 + sashWaveR * 0.5, 38, 16 + sashWaveR, 52, 23 + sashWaveR);
  ctx.bezierCurveTo(46, 30 + sashWaveR, 28, 25 + sashWaveR * 0.5, 8, 18);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = "rgba(255, 247, 160, 0.8)";
  ctx.lineWidth = 1.2;
  ctx.stroke();
  ctx.restore();

  // -----------------------------------------------------------------------
  // 4. LỚP 3: MŨ NGÔI SAO HOÀNG KIM 3 CÁNH (3-POINTED GOLDEN STAR HELM)
  // -----------------------------------------------------------------------
  ctx.save();
  const starTopY  = -46;
  const starLeftX = -46, starLeftY = -9;
  const starRightX= 46,  starRightY= -9;

  ctx.shadowColor = "rgba(202, 138, 4, 0.35)";
  ctx.shadowBlur = 10;

  const starGrad = ctx.createRadialGradient(-4, -20, 8, 0, -16, 48);
  starGrad.addColorStop(0, "#FFF7A0");
  starGrad.addColorStop(0.2, "#FEF08A");
  starGrad.addColorStop(0.6, "#FACC15");
  starGrad.addColorStop(0.85, "#EAB308");
  starGrad.addColorStop(1, "#CA8A04");
  ctx.fillStyle = starGrad;

  ctx.beginPath();
  ctx.moveTo(0, starTopY);
  ctx.bezierCurveTo(-14, -30, -22, -22, starLeftX, starLeftY);
  ctx.bezierCurveTo(-26, 0, -18, -2, -18, -10);
  ctx.bezierCurveTo(-10, -5, 10, -5, 18, -10);
  ctx.bezierCurveTo(18, -2, 26, 0, starRightX, starRightY);
  ctx.bezierCurveTo(22, -22, 14, -30, 0, starTopY);
  ctx.closePath();
  ctx.fill();

  ctx.strokeStyle = "rgba(255, 247, 160, 0.9)";
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.moveTo(0, starTopY); ctx.lineTo(-2, -16);
  ctx.moveTo(starLeftX, starLeftY); ctx.lineTo(-14, -16);
  ctx.moveTo(starRightX, starRightY); ctx.lineTo(14, -16);
  ctx.stroke();

  const underGrad = ctx.createLinearGradient(0, -16, 0, 0);
  underGrad.addColorStop(0, "rgba(202, 138, 4, 0)");
  underGrad.addColorStop(1, "rgba(133, 77, 14, 0.45)");
  ctx.fillStyle = underGrad;
  ctx.beginPath();
  ctx.moveTo(starLeftX, starLeftY);
  ctx.bezierCurveTo(-20, 2, 20, 2, starRightX, starRightY);
  ctx.bezierCurveTo(16, -10, -16, -10, starLeftX, starLeftY);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // -----------------------------------------------------------------------
  // 5. LỚP 4: 3 DẢI BÙA NGUYỆN ƯỚC XANH NGỌC LAM (TANZAKU WISH TAGS)
  // -----------------------------------------------------------------------
  ctx.save();
  function drawTanzakuTag(bx, by, lag, w, h) {
    ctx.save();
    const wave1 = Math.sin(lag) * 2.8;
    const wave2 = Math.sin(lag + 0.4) * 4.2;

    ctx.shadowColor = "rgba(6, 182, 212, 0.4)";
    ctx.shadowBlur = 6;

    const tagGrad = ctx.createLinearGradient(bx, by, bx + wave2, by + h);
    tagGrad.addColorStop(0, "#22D3EE");
    tagGrad.addColorStop(0.5, "#06B6D4");
    tagGrad.addColorStop(1, "#0E7490");
    ctx.fillStyle = tagGrad;

    ctx.beginPath();
    ctx.moveTo(bx - w / 2, by);
    ctx.bezierCurveTo(bx - w / 2 + wave1, by + h * 0.4, bx - w / 2 + wave2, by + h * 0.8, bx - w / 2 + wave2, by + h);
    ctx.lineTo(bx + w / 2 + wave2, by + h);
    ctx.bezierCurveTo(bx + w / 2 + wave2, by + h * 0.8, bx + w / 2 + wave1, by + h * 0.4, bx + w / 2, by);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = "#A5F3FC";
    ctx.lineWidth = 1.0;
    ctx.stroke();

    ctx.strokeStyle = "#CFFAFE";
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(bx + wave1 * 0.5, by + 4);
    ctx.lineTo(bx + wave1 * 0.8, by + h * 0.5);
    ctx.lineTo(bx + wave2 * 0.9, by + h - 4);
    ctx.stroke();

    ctx.restore();
  }

  drawTanzakuTag(0, starTopY + 2, lagTagTop, 8, 25);
  drawTanzakuTag(starLeftX + 2, starLeftY + 1, lagTagLeft, 7, 27);
  drawTanzakuTag(starRightX - 2, starRightY + 1, lagTagRight, 7, 27);
  ctx.restore();

  // -----------------------------------------------------------------------
  // 6. LỚP 5: THÂN TRẮNG SỮA & CHÂN MŨM MĨM (PORCELAIN CHUBBY BODY & FEET)
  // -----------------------------------------------------------------------
  ctx.save();
  const bodyY = 14;
  const bRx   = 16 * sX;
  const bRy   = 15 * sY;

  ctx.fillStyle = "#F8FAFC";
  ctx.strokeStyle = "#E2E8F0";
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.ellipse(-7, 26, 4.5 * sX, 4 * sY, 0.1, 0, Math.PI * 2);
  ctx.ellipse(7,  26, 4.5 * sX, 4 * sY, -0.1, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();

  const bodyGrad = ctx.createRadialGradient(-3, bodyY - 4, 3, 0, bodyY, 20);
  bodyGrad.addColorStop(0, "#FFFFFF");
  bodyGrad.addColorStop(0.5, "#F8FAFC");
  bodyGrad.addColorStop(0.85, "#F1F5F9");
  bodyGrad.addColorStop(1, "#E2E8F0");
  ctx.fillStyle = bodyGrad;
  ctx.beginPath();
  ctx.ellipse(0, bodyY, bRx, bRy, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = "#E2E8F0";
  ctx.lineWidth = 1.0;
  ctx.stroke();

  // -----------------------------------------------------------------------
  // 7. LỚP 6: MẮT THỨ BA TRÊN BỤNG (TRUE EYE OF TRUTH)
  // -----------------------------------------------------------------------
  ctx.save();
  const thirdEyeY = 16;
  const eyeW = 12 * sX;
  ctx.strokeStyle = "#0F172A";
  ctx.lineWidth = 1.8;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.arc(0, thirdEyeY - 2, eyeW * 0.7, 0.3 * Math.PI, 0.7 * Math.PI, false);
  ctx.stroke();

  ctx.strokeStyle = "rgba(148, 163, 184, 0.5)";
  ctx.lineWidth = 1.0;
  ctx.beginPath();
  ctx.arc(0, thirdEyeY - 1, eyeW * 0.72, 0.32 * Math.PI, 0.68 * Math.PI, false);
  ctx.stroke();
  ctx.restore();

  // -----------------------------------------------------------------------
  // 8. LỚP 7: HAI TAY MŨM MĨM DANG RỘNG (CHUBBY ARMS)
  // -----------------------------------------------------------------------
  ctx.save();
  const armGradL = ctx.createLinearGradient(-10, 10, -24, 16);
  armGradL.addColorStop(0, "#F8FAFC");
  armGradL.addColorStop(1, "#FFFFFF");
  ctx.fillStyle = armGradL;
  ctx.strokeStyle = "#E2E8F0";
  ctx.lineWidth = 1.1;

  ctx.beginPath();
  ctx.moveTo(-10, 9);
  ctx.lineTo(-24, 15);
  ctx.lineTo(-24, 17);
  ctx.lineTo(-11, 16);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(10, 9);
  ctx.lineTo(24, 15);
  ctx.lineTo(24, 17);
  ctx.lineTo(11, 16);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.restore();

  // -----------------------------------------------------------------------
  // 9. LỚP 8: ĐẦU & KHUÔN MẶT BÁNH BAO (CHUBBY PORCELAIN HEAD)
  // -----------------------------------------------------------------------
  ctx.save();
  const headY = -6;
  const hRx   = 21 * sX;
  const hRy   = 15 * sY;

  const headGrad = ctx.createRadialGradient(-3, headY - 4, 4, 0, headY, 24);
  headGrad.addColorStop(0, "#FFFFFF");
  headGrad.addColorStop(0.6, "#F8FAFC");
  headGrad.addColorStop(0.9, "#F1F5F9");
  headGrad.addColorStop(1, "#E2E8F0");
  ctx.fillStyle = headGrad;
  ctx.beginPath();
  ctx.ellipse(0, headY, hRx, hRy, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = "#E2E8F0";
  ctx.lineWidth = 1.0;
  ctx.stroke();
  ctx.restore();

  // -----------------------------------------------------------------------
  // 10. LỚP 9: HAI TAI MŨ SAO VÀNG RỦ XUỐNG HAI BÊN MÁ (STAR LAPPETS)
  // -----------------------------------------------------------------------
  ctx.save();
  function drawLappet(lx, ly, sway, isRight) {
    ctx.save();
    ctx.translate(lx, ly);
    ctx.rotate((sway * Math.PI) / 180 * (isRight ? 1 : -1));

    const lapGrad = ctx.createLinearGradient(-4, 0, 4, 20);
    lapGrad.addColorStop(0, "#FFF7A0");
    lapGrad.addColorStop(0.3, "#FACC15");
    lapGrad.addColorStop(0.8, "#EAB308");
    lapGrad.addColorStop(1, "#CA8A04");
    ctx.fillStyle = lapGrad;

    ctx.beginPath();
    ctx.roundRect(-4, 0, 8, 20, [4, 4, 5, 5]);
    ctx.fill();
    ctx.strokeStyle = "rgba(202, 138, 4, 0.6)";
    ctx.lineWidth = 1.0;
    ctx.stroke();
    ctx.restore();
  }

  drawLappet(-18, -8, lappetSway, false);
  drawLappet(18, -8, lappetSway, true);
  ctx.restore();

  // -----------------------------------------------------------------------
  // 11. LỚP 10: CHI TIẾT BIỂU CẢM & MÁ HỒNG (BLUSH & TEARS & SMILE)
  // -----------------------------------------------------------------------
  ctx.save();
  const blushGradL = ctx.createRadialGradient(-13, headY + 3, 1, -13, headY + 3, 6);
  blushGradL.addColorStop(0, "rgba(244, 114, 182, 0.65)");
  blushGradL.addColorStop(0.6, "rgba(251, 207, 232, 0.35)");
  blushGradL.addColorStop(1, "rgba(251, 207, 232, 0)");
  ctx.fillStyle = blushGradL;
  ctx.beginPath();
  ctx.arc(-13, headY + 3, 6, 0, Math.PI * 2);
  ctx.fill();

  const blushGradR = ctx.createRadialGradient(13, headY + 3, 1, 13, headY + 3, 6);
  blushGradR.addColorStop(0, "rgba(244, 114, 182, 0.65)");
  blushGradR.addColorStop(0.6, "rgba(251, 207, 232, 0.35)");
  blushGradR.addColorStop(1, "rgba(251, 207, 232, 0)");
  ctx.fillStyle = blushGradR;
  ctx.beginPath();
  ctx.arc(13, headY + 3, 6, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = "#0284C7";
  ctx.beginPath();
  ctx.moveTo(-10, headY + 1); ctx.lineTo(-12, headY + 6); ctx.lineTo(-8, headY + 6); ctx.closePath(); ctx.fill();
  ctx.beginPath();
  ctx.moveTo(10, headY + 1); ctx.lineTo(8, headY + 6); ctx.lineTo(12, headY + 6); ctx.closePath(); ctx.fill();

  ctx.strokeStyle = "#334155";
  ctx.lineWidth = 1.4;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.arc(0, headY + 3, 3, 0.2 * Math.PI, 0.8 * Math.PI, false);
  ctx.stroke();
  ctx.restore();

  // -----------------------------------------------------------------------
  // 12. LỚP 11: ĐÔI MẮT PHA LÊ 3 ĐIỂM BẮT SÁNG (3-POINT SPECULAR CRYSTAL EYES)
  // -----------------------------------------------------------------------
  ctx.save();
  const eyeY = headY - 1;
  const eyeXL = -10, eyeXR = 10;

  if (blink) {
    ctx.strokeStyle = "#020617";
    ctx.lineWidth = 2.0;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(eyeXL, eyeY + 1, 5, 0.2 * Math.PI, 0.8 * Math.PI, false);
    ctx.arc(eyeXR, eyeY + 1, 5, 0.2 * Math.PI, 0.8 * Math.PI, false);
    ctx.stroke();
  } else {
    [eyeXL, eyeXR].forEach(ex => {
      ctx.save();
      const eyeGrad = ctx.createRadialGradient(ex - 1, eyeY - 2, 1, ex, eyeY, 7);
      eyeGrad.addColorStop(0, "#1E1B4B");
      eyeGrad.addColorStop(0.4, "#0F172A");
      eyeGrad.addColorStop(1, "#020617");
      ctx.fillStyle = eyeGrad;
      ctx.beginPath();
      ctx.ellipse(ex, eyeY, 5, 7, 0, 0, Math.PI * 2);
      ctx.fill();

      const causticGrad = ctx.createLinearGradient(ex, eyeY + 2, ex, eyeY + 7);
      causticGrad.addColorStop(0, "rgba(56, 189, 248, 0)");
      causticGrad.addColorStop(1, "rgba(56, 189, 248, 0.85)");
      ctx.fillStyle = causticGrad;
      ctx.beginPath();
      ctx.ellipse(ex, eyeY + 4, 3.5, 2.2, 0, 0, Math.PI * 2);
      ctx.fill();

      // ĐIỂM SÁNG 1: Khối 2x2 góc 10h
      ctx.fillStyle = "#FFFFFF";
      ctx.beginPath();
      ctx.arc(ex - 1.8, eyeY - 2.5, 1.8, 0, Math.PI * 2);
      ctx.fill();

      // ĐIỂM SÁNG 2: Phản xạ phụ góc 4h
      ctx.fillStyle = "#E0F2FE";
      ctx.beginPath();
      ctx.arc(ex + 1.8, eyeY + 2.4, 1.0, 0, Math.PI * 2);
      ctx.fill();

      // ĐIỂM SÁNG 3: Bắt sáng ướt góc 2h
      ctx.fillStyle = "#FFFFFF";
      ctx.beginPath();
      ctx.arc(ex + 1.6, eyeY - 1.6, 0.7, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    });
  }
  ctx.restore();

  // -----------------------------------------------------------------------
  // 13. LỚP 12: HÀO QUANG BỤI SAO & KIM CƯƠNG THIÊN HÀ (STARDUST SPARKLES ✨)
  // -----------------------------------------------------------------------
  ctx.save();
  function drawDiamondSparkle(x, y, r, color) {
    ctx.save();
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y - r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.quadraticCurveTo(x, y, x, y + r);
    ctx.quadraticCurveTo(x, y, x - r, y);
    ctx.quadraticCurveTo(x, y, x, y - r);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "#FFFFFF";
    ctx.beginPath(); ctx.arc(x, y, r * 0.35, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }

  const sparkPulse = 1.0 + 0.3 * Math.sin(t * 4.0);
  drawDiamondSparkle(0, starTopY - 6, 5 * sparkPulse, "#FFF7A0");
  drawDiamondSparkle(starLeftX - 6, starLeftY - 2, 3.5 * sparkPulse, "#67E8F9");
  drawDiamondSparkle(starRightX + 6, starRightY - 2, 3.5 * sparkPulse, "#FDE047");

  const orb1X = -18 + Math.sin(t * 2.2) * 4.0;
  const orb1Y = 18 + Math.cos(t * 2.2) * 3.0;
  ctx.fillStyle = "rgba(254, 240, 138, 0.85)";
  ctx.beginPath(); ctx.arc(orb1X, orb1Y, 1.2, 0, Math.PI * 2); ctx.fill();

  const orb2X = 18 - Math.cos(t * 2.0) * 4.0;
  const orb2Y = 16 + Math.sin(t * 2.0) * 3.0;
  ctx.fillStyle = "rgba(103, 232, 249, 0.85)";
  ctx.beginPath(); ctx.arc(orb2X, orb2Y, 1.2, 0, Math.PI * 2); ctx.fill();

  ctx.restore();

  ctx.restore(); // Restore root translation
}
